  return {
    providerId: "claude",
    runStructured: async <T = unknown>(request: StructuredAgentRequest) => {
      const args = ["--print", "--output-format", "stream-json", "--cwd", request.projectPath, request.prompt];
      const { stdout, stderr } = await runCommand(command, args, { cwd: request.projectPath, signal: request.signal });
      const rawResponse = stdout.trim() || stderr.trim();
      if (!rawResponse) throw new Error("Claude did not return any output.");
      let events: Record<string, unknown>[];
      try {
        events = parseJsonLines(rawResponse);
      } catch {
        throw new Error("Claude did not return valid stream-json output.");
      }
      return {
        providerId: "claude",
        output: extractStructuredOutput<T>(events),
        rawResponse,
        providerSessionRef: sessionRefFor(extractSessionId(events))
      };
    },
    runText: async (request: TextAgentRequest) => {
      const args = ["--print", "--output-format", "stream-json", "--cwd", request.projectPath];
      if (request.providerSessionRef?.externalId) {
        args.push("--resume", request.providerSessionRef.externalId);
      }
      args.push(request.prompt);
      const { stdout, stderr } = await runCommand(command, args, { cwd: request.projectPath, signal: request.signal });
      const rawResponse = stdout.trim() || stderr.trim();
      if (!rawResponse) throw new Error("Claude did not return any output.");
      let events: Record<string, unknown>[];
      try {
        events = parseJsonLines(rawResponse);
      } catch {
        throw new Error("Claude did not return valid stream-json output.");
      }
      const text = events.map(extractEventText).filter((value): value is string => Boolean(value)).join("\n").trim();
      if (!text) throw new Error("Claude did not return a text response.");
      return {
        providerId: "claude",
        text,
        rawResponse,
        providerSessionRef: sessionRefFor(extractSessionId(events) ?? request.providerSessionRef?.externalId ?? null)
      };
    }
  };
};

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { AgentProvider, CliCommandRunner, StructuredAgentRequest, TextAgentRequest } from "./index";
import { parseStructuredAgentJsonResponse } from "./index";

const execFileAsync = promisify(execFile);

const defaultRunCommand: CliCommandRunner = async (command, args, options) => {
  const result = await execFileAsync(command, [...args], {
    cwd: options.cwd,
    signal: options.signal,
    maxBuffer: 10 * 1024 * 1024
  });
  return {
    stdout: result.stdout ?? "",
    stderr: result.stderr ?? ""
  };
};

const parseJsonLines = (value: string): unknown[] =>
  value
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line)];
      } catch {
        return [];
      }
    });

const extractSessionId = (payload: unknown): string | null => {
  if (!payload || typeof payload !== "object") return null;
  const record = payload as Record<string, unknown>;
  const value = record.sessionId ?? record.session_id ?? record.conversationId ?? record.conversation_id ?? record.threadId ?? record.id;
  return typeof value === "string" && value.trim() ? value.trim() : null;
};

const extractText = (payload: unknown): string | null => {
  if (typeof payload === "string" && payload.trim()) return payload.trim();
  if (!payload || typeof payload !== "object") return null;
  const record = payload as Record<string, unknown>;
  for (const key of ["text", "message", "output", "result", "response", "content"]) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return null;
};

const parseCursorPayload = (stdout: string, stderr: string): unknown => {
  const trimmedStdout = stdout.trim();
  if (trimmedStdout) {
    try {
      return JSON.parse(trimmedStdout);
    } catch {
      const linePayloads = parseJsonLines(trimmedStdout);
      if (linePayloads.length > 0) return linePayloads.at(-1);
    }
  }

  const trimmedStderr = stderr.trim();
  if (trimmedStderr) {
    const linePayloads = parseJsonLines(trimmedStderr);
    if (linePayloads.length > 0) return linePayloads.at(-1);
  }

  throw new Error("Cursor did not return machine-readable output. Check that Cursor CLI supports --print --format json.");
};

const structuredOutputFromPayload = <T>(payload: unknown): T => {
  if (payload && typeof payload === "object") {
    const record = payload as Record<string, unknown>;
    const nested = record.output ?? record.result ?? record.response ?? record.content;
    if (nested && typeof nested === "object") return nested as T;
    if (typeof nested === "string") return parseStructuredAgentJsonResponse(nested) as T;
  }
  if (typeof payload === "string") return parseStructuredAgentJsonResponse(payload) as T;
  return payload as T;
};

export type CursorProviderDependencies = {
  readonly command?: string;
  readonly runCommand?: CliCommandRunner;
};

const sessionRefFor = (sessionId: string | null) =>
  sessionId
    ? {
        providerId: "cursor",
        externalId: sessionId,
        parts: { sessionId }
      }
    : null;

export const createCursorAgentProvider = (dependencies: CursorProviderDependencies = {}): AgentProvider => {
  const command = dependencies.command ?? "cursor";
  const runCommand = dependencies.runCommand ?? defaultRunCommand;

  return {
    providerId: "cursor",
    runStructured: async <T = unknown>(request: StructuredAgentRequest) => {
      const { stdout, stderr } = await runCommand(
        command,
        ["agent", "--print", "--format", "json", "--cwd", request.projectPath, request.prompt],
        { cwd: request.projectPath, signal: request.signal }
      );
      const payload = parseCursorPayload(stdout, stderr);
      return {
        providerId: "cursor",
        output: structuredOutputFromPayload<T>(payload),
        rawResponse: stdout.trim() || stderr.trim(),
        providerSessionRef: sessionRefFor(extractSessionId(payload))
      };
    },
    runText: async (request: TextAgentRequest) => {
      const args = ["agent", "--print", "--cwd", request.projectPath];
      if (request.providerSessionRef?.externalId) {
        args.push("--resume", request.providerSessionRef.externalId);
      }
      args.push(request.prompt);
      const { stdout, stderr } = await runCommand(command, args, { cwd: request.projectPath, signal: request.signal });
      const payload = parseCursorPayload(stdout, stderr);
      const text = extractText(payload) ?? stdout.trim();
      if (!text) throw new Error("Cursor did not return a text response.");
      return {
        providerId: "cursor",
        text,
        rawResponse: stdout.trim() || stderr.trim(),
        providerSessionRef: sessionRefFor(extractSessionId(payload) ?? request.providerSessionRef?.externalId ?? null)
      };
    }
  };
};

